export const THEMES_CSS = "/* report-themes.css — multi-theme token system.\n   Pattern: :root for the default, [data-theme=\"X\"] for alternates.\n   The switcher sets document.documentElement.dataset.theme and persists\n   to localStorage. All components consume only these tokens. */\n\n:root {\n  /* ── SCENE (default: P31 dark cover, warm content, cyan accent) ── */\n  --cover-bg: #0D0D12;\n  --cover-text: #E6F1FF;\n  --cover-muted: #8FA3B5;\n  --page-bg: #FAF7F2;\n  --page-surface: #FDFCFA;\n  --page-raised: #F2EDE6;\n  --text-primary: #1A1A1A;\n  --text-secondary: #57606A;\n  --text-muted: #8B949E;\n  --border: #E6E4DC;\n  --border-strong: #D4D0C5;\n  --accent: #2BB3D9;\n  --accent-soft: #E5F6FB;\n  --accent-text: #0E7FA8;\n  --accent-hot: var(--accent);\n  --ok: #1F9D55;\n  --ok-soft: #EAF2ED;\n  --warn: #B7791F;\n  --warn-soft: #FEF3CD;\n  --danger: #C0392B;\n  --danger-soft: #FDE8E8;\n  --font-display: 'DejaVu Serif', 'Lora', Georgia, serif;\n  --font-body: 'DejaVu Sans', 'Plus Jakarta Sans', system-ui, sans-serif;\n  --font-mono: 'DejaVu Sans Mono', 'JetBrains Mono', ui-monospace, monospace;\n}\n\n[data-theme=\"editorial\"] {\n  /* ── EDITORIAL (warm parchment, ink blue, serif-forward) ── */\n  --cover-bg: #1B365D;\n  --cover-text: #F5F4ED;\n  --cover-muted: #A8B5C8;\n  --page-bg: #F5F4ED;\n  --page-surface: #FDFCF8;\n  --page-raised: #EBE8DE;\n  --text-primary: #141210;\n  --text-secondary: #5A544C;\n  --text-muted: #8A8278;\n  --border: #E2DDD0;\n  --border-strong: #CFC7B6;\n  --accent: #1B365D;\n  --accent-soft: #E8EDF4;\n  --accent-text: #1B365D;\n  --ok: #2E7D4F;\n  --ok-soft: #E7F1EB;\n  --warn: #A66A0F;\n  --warn-soft: #FBF1DE;\n  --danger: #A8322A;\n  --danger-soft: #F7E5E3;\n  --font-display: 'DejaVu Serif', 'Lora', Georgia, serif;\n  --font-body: 'DejaVu Sans', system-ui, sans-serif;\n  --font-mono: 'DejaVu Sans Mono', ui-monospace, monospace;\n}\n\n[data-theme=\"consulting\"] {\n  /* ── CONSULTING (McKinsey-adjacent: navy, white, clean sans) ── */\n  --cover-bg: #1A365D;\n  --cover-text: #FFFFFF;\n  --cover-muted: #A0B4CC;\n  --page-bg: #FFFFFF;\n  --page-surface: #F7FAFC;\n  --page-raised: #EBF4FF;\n  --text-primary: #1A202C;\n  --text-secondary: #4A5568;\n  --text-muted: #718096;\n  --border: #E2E8F0;\n  --border-strong: #CBD5E0;\n  --accent: #3182CE;\n  --accent-soft: #EBF4FF;\n  --accent-text: #2C5282;\n  --ok: #2F855A;\n  --ok-soft: #F0FFF4;\n  --warn: #C05621;\n  --warn-soft: #FFFAF0;\n  --danger: #C53030;\n  --danger-soft: #FFF5F5;\n  --font-display: 'DejaVu Sans', system-ui, sans-serif;\n  --font-body: 'DejaVu Sans', system-ui, sans-serif;\n  --font-mono: 'DejaVu Sans Mono', ui-monospace, monospace;\n}\n\n[data-theme=\"midnight\"] {\n  /* ── MIDNIGHT (full dark for screen reading) ── */\n  --cover-bg: #0A0A0F;\n  --cover-text: #E4E4EB;\n  --cover-muted: #6E7681;\n  --page-bg: #111118;\n  --page-surface: #1A1A22;\n  --page-raised: #22222C;\n  --text-primary: #E4E4EB;\n  --text-secondary: #A8A8B3;\n  --text-muted: #6E7681;\n  --border: #2A2A35;\n  --border-strong: #3A3A48;\n  --accent: #4CC9F0;\n  --accent-soft: #0F2A38;\n  --accent-text: #4CC9F0;\n  --ok: #4ADE80;\n  --ok-soft: #0F2A1A;\n  --warn: #FBBF24;\n  --warn-soft: #2A2010;\n  --danger: #F87171;\n  --danger-soft: #2A1010;\n  --font-display: 'DejaVu Serif', Georgia, serif;\n  --font-body: 'DejaVu Sans', system-ui, sans-serif;\n  --font-mono: 'DejaVu Sans Mono', monospace;\n}\n\n/* Auto-select midnight for dark-mode readers; scene otherwise. */\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme]) { color-scheme: dark; }\n}\n\n[data-theme=\"ink\"] {\n  /* ── INK (paper-friendly light: printers, courts, lenders. Same accents,\n     light sheet. Default for letter/grant/brief/table-report templates) ── */\n  --cover-bg: #141416;\n  --cover-text: #ffffff;\n  --cover-muted: #9aa0a6;\n  --page-bg: #ffffff;\n  --page-surface: #f6f4ef;\n  --page-raised: #ece9e1;\n  --text-primary: #1a1a1a;\n  --text-secondary: #4f4b45;\n  --text-muted: #76716a;\n  --border: #e0dcd2;\n  --border-strong: #cfc8ba;\n  --accent: #c05621;\n  --accent-soft: #fbeee6;\n  --accent-text: #a44718;\n  --accent-hot: #b45309;\n  --ok: #1f9d55;\n  --ok-soft: #e8f4ec;\n  --warn: #b7791f;\n  --warn-soft: #fdf3e0;\n  --danger: #c0392b;\n  --danger-soft: #fbe9e7;\n  --font-display: 'DejaVu Serif', Georgia, serif;\n  --font-body: 'DejaVu Sans', system-ui, sans-serif;\n  --font-mono: 'DejaVu Sans Mono', 'Courier New', monospace;\n}\n\n[data-theme=\"professional\"] {\n  /* ── PROFESSIONAL (white paper, navy accent — grants, letters, guides) ── */\n  --cover-bg: #0F172A;\n  --cover-text: #F8FAFC;\n  --cover-muted: #94A3B8;\n  --page-bg: #FFFFFF;\n  --page-surface: #F8FAFC;\n  --page-raised: #EEF2F7;\n  --text-primary: #0F172A;\n  --text-secondary: #475569;\n  --text-muted: #4B5563;\n  --border: #E2E8F0;\n  --border-strong: #CBD5E1;\n  --accent: #1E40AF;\n  --accent-soft: #EFF6FF;\n  --accent-text: #1D4ED8;\n  --accent-hot: #1D4ED8;\n  --ok: #16A34A;\n  --ok-soft: #EAF7EF;\n  --warn: #D97706;\n  --warn-soft: #FDF3E3;\n  --danger: #DC2626;\n  --danger-soft: #FDEBEB;\n  --font-display: 'DejaVu Serif', Georgia, serif;\n  --font-body: 'DejaVu Sans', system-ui, sans-serif;\n  --font-mono: 'DejaVu Sans Mono', 'Courier New', monospace;\n}\n\n[data-theme=\"family\"] {\n  /* ── FAMILY (warm cream, amber accent, serif — letters home) ── */\n  --cover-bg: #2D2416;\n  --cover-text: #FDF8F0;\n  --cover-muted: #9C8C7A;\n  --page-bg: #FDF8F0;\n  --page-surface: #FFFFFF;\n  --page-raised: #F3EADC;\n  --text-primary: #2D2416;\n  --text-secondary: #6B5D4F;\n  --text-muted: #7A6B5B;\n  --border: #E8DFD0;\n  --border-strong: #D4C5B0;\n  --accent: #B45309;\n  --accent-soft: #FEF3C7;\n  --accent-text: #92400E;\n  --accent-hot: #92400E;\n  --ok: #4D7C0F;\n  --ok-soft: #F2F7E8;\n  --warn: #B45309;\n  --warn-soft: #FDF1DF;\n  --danger: #B91C1C;\n  --danger-soft: #FBE9E9;\n  --font-display: 'DejaVu Serif', Georgia, serif;\n  --font-body: 'DejaVu Serif', Georgia, serif;\n  --font-mono: 'DejaVu Sans Mono', 'Courier New', monospace;\n}\n\n[data-theme=\"friends\"] {\n  /* ── FRIENDS (warm white, orange accent, sans — casual, intentional) ── */\n  --cover-bg: #1C1917;\n  --cover-text: #FFF7ED;\n  --cover-muted: #A8A29E;\n  --page-bg: #FFF7ED;\n  --page-surface: #FFFFFF;\n  --page-raised: #FFEDD5;\n  --text-primary: #1C1917;\n  --text-secondary: #57534E;\n  --text-muted: #57534E;\n  --border: #FED7AA;\n  --border-strong: #FDBA74;\n  --accent: #EA580C;\n  --accent-soft: #FFF3E4;\n  --accent-text: #C2410C;\n  --accent-hot: #C2410C;\n  --ok: #16A34A;\n  --ok-soft: #EAF7EF;\n  --warn: #D97706;\n  --warn-soft: #FDF3E3;\n  --danger: #DC2626;\n  --danger-soft: #FDEBEB;\n  --font-display: 'DejaVu Sans', system-ui, sans-serif;\n  --font-body: 'DejaVu Sans', system-ui, sans-serif;\n  --font-mono: 'DejaVu Sans Mono', 'Courier New', monospace;\n}\n\n[data-theme=\"ops\"] {\n  /* ── OPS (dark console, sky blue, mono display — runbooks) ── */\n  --cover-bg: #0B1220;\n  --cover-text: #E2E8F0;\n  --cover-muted: #64748B;\n  --page-bg: #0F172A;\n  --page-surface: #1E293B;\n  --page-raised: #16233B;\n  --text-primary: #E2E8F0;\n  --text-secondary: #94A3B8;\n  --text-muted: #94A3B8;\n  --border: rgba(148, 163, 184, 0.16);\n  --border-strong: rgba(56, 189, 248, 0.40);\n  --accent: #38BDF8;\n  --accent-soft: rgba(56, 189, 248, 0.10);\n  --accent-text: #38BDF8;\n  --accent-hot: #7DD3FC;\n  --ok: #4ADE80;\n  --ok-soft: rgba(74, 222, 128, 0.08);\n  --warn: #FBBF24;\n  --warn-soft: rgba(251, 191, 36, 0.08);\n  --danger: #F87171;\n  --danger-soft: rgba(248, 113, 113, 0.08);\n  --font-display: 'DejaVu Sans Mono', 'Courier New', monospace;\n  --font-body: 'DejaVu Sans', system-ui, sans-serif;\n  --font-mono: 'DejaVu Sans Mono', 'Courier New', monospace;\n}\n\n[data-theme=\"ats\"] {\n  /* ── ATS (grounded in the ATS Accelerator 2026 PDF: navy void, teal mint,\n     neon green, slate text, Courier-style mono) ── */\n  --cover-bg: #090d17;\n  --cover-text: #e0e4ec;\n  --cover-muted: #64748b;\n  --page-bg: #090d17;\n  --page-surface: #1d293b;\n  --page-raised: #0e1729;\n  --text-primary: #e0e4ec;\n  --text-secondary: #a5b1c5;\n  --text-muted: #64748b;\n  --border: rgba(148, 163, 184, 0.16);\n  --border-strong: rgba(94, 234, 212, 0.40);\n  --accent: #5eead4;\n  --accent-soft: rgba(94, 234, 212, 0.10);\n  --accent-text: #5eead4;\n  --accent-hot: #39ff14;\n  --ok: #39ff14;\n  --ok-soft: rgba(57, 255, 20, 0.07);\n  --warn: #fbbf24;\n  --warn-soft: rgba(251, 191, 36, 0.08);\n  --danger: #ff6b6b;\n  --danger-soft: rgba(255, 107, 107, 0.08);\n  --font-display: 'DejaVu Sans', system-ui, sans-serif;\n  --font-body: 'DejaVu Sans', system-ui, sans-serif;\n  --font-mono: 'DejaVu Sans Mono', 'Courier New', monospace;\n}";
export const LAYOUT_CSS = "/* P31 Forge layout layer v2 — universal across all document templates.\n   Inlined by scripts/template.mjs in this exact order (NEVER @import: the\n   HTML is written to /tmp/report/, relative URLs would 404):\n     @layer reset, tokens, base, components, layout, print;\n     @layer tokens     { report-themes.css }\n     @layer base       { report.css  — with every @page block REMOVED }\n     @layer components { components.css (optional) }\n     @layer layout     { this file }\n   then pages.css unlayered. Unlayered CSS beats layered CSS regardless of order.\n   FRAGMENTATION NOTE (verified experiment, 2026-10-12, Chromium 150): grid and\n   flex containers fragment cleanly between rows/items and honor\n   break-inside:avoid on children. display:grid/flex are safe in print here. */\n\n@layer layout {\n  /* ---- Pages emitted by pack-pages.mjs (children of main.page only, so the\n     outer wrapper never breaks and adds a trailing blank page) ---- */\n  main.page > .page { break-after: page; break-inside: avoid; position: relative; }\n  main.page > .page:last-child { break-after: auto; }\n  /* The packed page is the boundary: a unit's inter-section bottom margin is\n     spacing BETWEEN sections, not padding after the page's last unit. Without\n     this, every .page measures ~60px taller than the packer's fill math. */\n  main.page > .page > :last-child { margin-bottom: 0; }\n  main.page > .page.force-break, .chapter.force-break { break-before: page; }\n  .pagebreak { break-before: page; }\n\n  /* ---- Width: the real cap is report.css `.body { max-width: 17cm }` ---- */\n  .chapter .body, .body, .prose, .data-table, .callout, .email, .kpi-strip,\n  .chapter p, .chapter ul, .chapter ol { max-width: none; width: 100%; }\n\n  /* ---- Columns ---- */\n  .cols-2 { column-count: 2; column-gap: 8mm; column-fill: balance; }\n  .cols-3 { column-count: 3; column-gap: 8mm;  column-fill: balance; }\n  .cols-2 > *, .cols-3 > * { break-inside: avoid; margin-top: 0; }\n\n  /* ---- Strips / grids (verified safe by experiment) ---- */\n  .metric-strip { display: grid;\n    grid-template-columns: repeat(var(--kpi-cols, 5), minmax(0, 1fr));\n    gap: 1px; }\n  .card-grid { display: grid; gap: 6mm;\n    grid-template-columns: repeat(var(--card-cols, 2), minmax(0, 1fr));\n    grid-auto-rows: 1fr; }\n\n  /* ---- Atoms never split ---- */\n  .kpi-card, .rec-card, .script-card, .callout, .email, .stat, .quote, .sig, figure, tr, .atom {\n    break-inside: avoid; }\n\n  /* ---- Keep-with ---- */\n  h1, h2, h3, h4, .section-kicker, .chapter-kicker { break-after: avoid; }\n  .section-kicker + h2 { break-before: avoid; }\n  .keep-with-next { break-after: avoid; }\n  .keep-with-prev { break-before: avoid; }\n  p { orphans: 2; widows: 2; }\n\n  /* ---- Tables (workspace Sheets export too) ---- */\n  .data-table { table-layout: fixed; border-collapse: collapse; width: 100%; }\n  .data-table td, .data-table th { overflow-wrap: anywhere; white-space: normal; }\n  thead { display: table-header-group; }\n  tfoot { display: table-footer-group; }\n\n  /* ---- Email / letter ---- */\n  .email { padding: 4mm 5mm; border-left: 1mm solid var(--accent); }\n  .email-subject { font-weight: 700; margin-bottom: 2mm; }\n  .email-greeting, .email-signoff { margin: 2mm 0; }\n  .email p { margin: 0 0 2mm; font-style: normal; }\n\n  /* ---- Signature / letter chrome ---- */\n  .letterhead { margin-bottom: 6mm; }\n  .letterhead .eyebrow { font-family: var(--font-mono); font-size: 8pt;\n    text-transform: uppercase; letter-spacing: 0.14em; color: var(--text-muted); }\n  .sig { margin-top: 6mm; }\n  .sig .sig-name { font-weight: 700; }\n  .sig .sig-line { color: var(--text-muted); font-size: 9pt; }\n\n  /* ---- Fit-to-page tiers (brief template): packer sets data-fit=\"1..3\" ---- */\n  .page[data-fit=\"1\"] { font-size: 100%; }\n  .page[data-fit=\"2\"] { font-size: 94%; --gap-scale: .85; }\n  .page[data-fit=\"3\"] { font-size: 88%; --gap-scale: .7; }\n}\n\n@layer print {\n  @media print { html, body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }\n}";
export const PAGES_CSS = "/* UNLAYERED. @page rules must never be placed inside @layer (Chromium drops them).\n   scripts/template.mjs replaces the __PLACEHOLDER__ tokens per template before\n   inlining: __PAGE_SIZE__ (\"11in 8.5in\" / \"8.5in 11in\"), __MARGIN__\n   (\"12mm 12mm 14mm 12mm\"), __PAGE_BG__ (#090d17 / #ffffff),\n   __FOOTER__ (running footer text or \"none\"), __FOOTER_COLOR__,\n   __ACCENT__ (page-number color). */\n@media print {\n  @page {\n    size: __PAGE_SIZE__;\n    margin: __MARGIN__;\n    background: __PAGE_BG__;\n    @bottom-center {\n      content: __FOOTER__;\n      font-family: 'DejaVu Sans Mono', monospace;\n      font-size: 9.6pt; color: __FOOTER_COLOR__;\n    }\n    @bottom-right {\n      content: 'PAGE ' counter(page);\n      font-family: 'DejaVu Sans Mono', monospace;\n      font-size: 9.6pt; color: __ACCENT__;\n    }\n  }\n  @page cover-page {\n    margin: 0;\n    @bottom-center { content: none; }\n    @bottom-right { content: none; }\n  }\n}\n.cover { page: cover-page; }";
export const THEME_PICKER_JS = "/* theme-picker.js — minimal theme switcher.\n   Sets document.documentElement.dataset.theme, persists to localStorage,\n   syncs on load. Zero dependencies. Hidden in print. */\n\n(function () {\n  var THEMES = [\n    { id: 'scene', label: 'Scene', swatch: '#2BB3D9' },\n    { id: 'editorial', label: 'Editorial', swatch: '#1B365D' },\n    { id: 'consulting', label: 'Consulting', swatch: '#3182CE' },\n    { id: 'midnight', label: 'Midnight', swatch: '#4CC9F0' },\n    { id: 'ats', label: 'ATS', swatch: '#5eead4' },\n    { id: 'professional', label: 'Professional', swatch: '#1E40AF' },\n    { id: 'family', label: 'Family', swatch: '#B45309' },\n    { id: 'friends', label: 'Friends', swatch: '#EA580C' },\n    { id: 'ops', label: 'Ops', swatch: '#38BDF8' },\n  ];\n\n  function apply(theme) {\n    document.documentElement.dataset.theme = theme;\n    try { localStorage.setItem('p31-report-theme', theme); } catch (e) {}\n    document.querySelectorAll('.theme-swatch').forEach(function (el) {\n      el.setAttribute('aria-pressed', String(el.dataset.setTheme === theme));\n    });\n  }\n\n  function init() {\n    var saved = null;\n    try { saved = localStorage.getItem('p31-report-theme'); } catch (e) {}\n    var prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;\n    // Only apply a saved/presumed theme if none is already set on <html>.\n    if (!document.documentElement.dataset.theme) {\n      var theme = saved || (prefersDark ? 'midnight' : 'scene');\n      document.documentElement.dataset.theme = theme;\n    }\n\n    var picker = document.createElement('div');\n    picker.className = 'theme-picker';\n    picker.setAttribute('role', 'group');\n    picker.setAttribute('aria-label', 'Report theme');\n    for (var i = 0; i < THEMES.length; i++) {\n      var t = THEMES[i];\n      var b = document.createElement('button');\n      b.className = 'theme-swatch';\n      b.type = 'button';\n      b.dataset.setTheme = t.id;\n      b.title = t.label;\n      b.setAttribute('aria-label', t.label);\n      b.style.background = t.swatch;\n      b.addEventListener('click', (function (id) { return function () { apply(id); }; })(t.id));\n      picker.appendChild(b);\n    }\n    document.body.appendChild(picker);\n    apply(document.documentElement.dataset.theme);\n  }\n\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', init);\n  } else {\n    init();\n  }\n})();";
export const INDEX_JSON = "{\n  \"_doc\": \"Doc-type registry. Each IR `type` resolves to a template file. `surface` maps the P31 Workspace app (workspace.p31ca.org) to the template its export uses.\",\n  \"types\": {\n    \"report\":       { \"template\": \"report.json\",       \"surface\": [\"Life\", \"Forum\"],        \"use\": \"Research reports, call kits, synthesis, briefings\" },\n    \"brief\":        { \"template\": \"brief.json\",        \"surface\": [\"Docs\"],                 \"use\": \"Hard one-page leave-behind / one-pager\" },\n    \"letter\":       { \"template\": \"letter.json\",       \"surface\": [\"Mail\", \"Docs\"],         \"use\": \"Letters, follow-up emails, formal correspondence\" },\n    \"memo\":         { \"template\": \"letter.json\",       \"surface\": [\"Docs\"],                 \"variant\": \"memo\", \"use\": \"Internal memos (letter template, memo header variant)\" },\n    \"deck\":         { \"template\": \"deck.json\",         \"surface\": [\"Slides\"],               \"use\": \"Page-per-unit decks, ATS-style\" },\n    \"grant\":        { \"template\": \"grant.json\",        \"surface\": [\"Docs\"],                 \"use\": \"Grant applications with word budgets and budget tables\" },\n    \"table-report\": { \"template\": \"table-report.json\", \"surface\": [\"Sheets\"],               \"use\": \"Dense tabular exports, ledgers, budgets\" },\n    \"agenda\":       { \"template\": \"agenda.json\",       \"surface\": [\"Calendar\"],             \"use\": \"Schedules, agendas, call sheets\" },\n    \"digest\":       { \"template\": \"report.json\",       \"surface\": [\"Forum\", \"Life\"],        \"variant\": \"digest\", \"use\": \"Q&A / log digests (report template, digest variant)\" },\n    \"credential\":   { \"template\": \"brief.json\",        \"surface\": [\"Passports\"],            \"variant\": \"credential\", \"use\": \"Passport / credential card sheets\" },\n    \"packet\":       { \"template\": \"packet.json\",       \"surface\": [\"Drive\"],                \"use\": \"Bundle several documents under one cover + contents\" },\n    \"runbook\":      { \"template\": \"runbook.json\",      \"surface\": [\"Docs\"],                 \"use\": \"Operational procedures: trigger, diagnosis, fix, verification, rollback\" },\n    \"guide\":        { \"template\": \"guide.json\",        \"surface\": [\"Docs\"],                 \"use\": \"How-to guides and long-form instructions\" },\n    \"family-letter\":{ \"template\": \"family-letter.json\",\"surface\": [\"Mail\"],                 \"use\": \"Letters home, family history, keepsake correspondence\" }\n  },\n  \"themes\": { \"ats\": \"dark full-bleed (screen + PDF)\", \"ink\": \"light, paper-friendly (printers, court, lenders)\" }\n}";
export const TEMPLATE_AGENDA = "{\n  \"name\": \"agenda\",\n  \"type\": \"agenda\",\n  \"page\": {\n    \"widthIn\": 8.5,\n    \"heightIn\": 11,\n    \"margin\": \"20mm 20mm 22mm 20mm\",\n    \"background\": \"#ffffff\"\n  },\n  \"defaultTheme\": \"ink\",\n  \"cover\": false,\n  \"packing\": {\n    \"mode\": \"flow\"\n  },\n  \"gates\": {\n    \"readability\": false,\n    \"pageCountRange\": [\n      1,\n      6\n    ]\n  },\n  \"footer\": \"P31 LABS\",\n  \"footerColor\": \"#8a8a8a\",\n  \"accent\": \"#c05621\",\n  \"themes\": [\n    \"professional\",\n    \"ink\"\n  ]\n}";
